import React, { useState, useEffect } from "react";
import { Menu, X } from "lucide-react";

const links = [
  { label: "About", href: "#about" },
  { label: "Collections", href: "#collections" },
  { label: "Portfolio", href: "#portfolio" },
  { label: "Contact", href: "#contact" },
];

export default function Navbar({ onOpenQuote }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header className={`fixed top-0 inset-x-0 z-40 transition-all duration-500 ${scrolled ? "py-3 bg-[#0d0405]/85 backdrop-blur-xl border-b border-[#d4af37]/15" : "py-6"}`}>
      <div className="flex items-center justify-between px-6 md:px-12 lg:px-24">
        <a href="#top" className="flex items-center gap-3">
          <span className="serif tracking-[0.3em] uppercase" style={{ fontSize: 14, color: "#d4af37", fontWeight: 500 }}>D Sajawat</span>
          <span className="hidden md:inline-block w-10 h-px" style={{ background: "rgba(212,175,55,0.5)" }} />
          <span className="hidden md:inline serif italic" style={{ color: "rgba(247,231,206,0.6)", fontSize: 13 }}>est. Ludhiana</span>
        </a>
        <nav className="hidden md:flex items-center gap-9">
          {links.map((l) => (
            <a key={l.href} href={l.href} className="text-sm tracking-wider transition-colors hover:text-[#f7e7ce]" style={{ color: "rgba(255,255,240,0.7)" }}>{l.label}</a>
          ))}
          <button onClick={onOpenQuote} className="btn-gold" style={{ padding: "10px 22px", fontSize: 13 }}>Request Quote</button>
        </nav>
        <button className="md:hidden text-[#f7e7ce]" onClick={() => setOpen((s) => !s)}><X size={22} /></button>
      </div>
      {open && (
        <div className="md:hidden mt-3 mx-6 glass gold-border rounded-sm p-6">
          <div className="flex flex-col gap-4">
            {links.map((l) => (
              <a key={l.href} href={l.href} onClick={() => setOpen(false)} className="serif text-2xl" style={{ color: "#f7e7ce" }}>{l.label}</a>
            ))}
            <button onClick={() => { setOpen(false); onOpenQuote(); }} className="btn-gold mt-2 self-start">Request Quote</button>
          </div>
        </div>
      )}
    </header>
  );
}
